import argparse
import pathlib

from slide_generator import make_thumbs
from slide_generator import mam_is_a_dataset, the_next_700_bibles, what_is_mam
from slide_generator import make_pptx

ALL_DECKS = {
    "what-is-mam": what_is_mam,
    "mam-is-a-dataset": mam_is_a_dataset,
    "the-next-700-bibles": the_next_700_bibles,
}


def cmd_render_slides(args: argparse.Namespace) -> None:
    deck = ALL_DECKS[args.deck]
    targets = [args.slide] if args.slide else list(deck.ALL_SLIDES)
    for name in targets:
        if name not in deck.ALL_SLIDES:
            raise SystemExit(
                f"Unknown slide {name!r} for deck {args.deck!r}. "
                f"Available: {', '.join(deck.ALL_SLIDES)}"
            )
        deck.ALL_SLIDES[name](html_only=args.html_only)


def cmd_make_thumbs(args: argparse.Namespace) -> None:
    if args.images_dir is None:
        args.images_dir = ALL_DECKS[args.deck].IMAGES_DIR
    make_thumbs.cmd_make_thumbs(args)


def cmd_make_pptx(args: argparse.Namespace) -> None:
    deck = ALL_DECKS[args.deck]
    if args.script is None:
        args.script = deck.IMAGES_DIR.parent / "script.md"
    if args.output is None:
        args.output = args.script.parent / f"{args.deck}.pptx"
    make_pptx.cmd_make_pptx(args)


def main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    sub = parser.add_subparsers(dest="subcommand", metavar="SUBCOMMAND")
    sub.required = True

    # -- make-thumbs --
    p_thumbs = sub.add_parser(
        "make-thumbs",
        help="Generate thumbnails from slide-*.png images.",
    )
    p_thumbs.add_argument(
        "--deck",
        required=True,
        choices=list(ALL_DECKS),
        metavar="DECK",
        help=f"slide deck to thumbnail (one of: {', '.join(ALL_DECKS)})",
    )
    p_thumbs.add_argument(
        "--images-dir",
        type=pathlib.Path,
        default=None,
        help="Directory containing slide-*.png files (default: deck's images dir)",
    )
    p_thumbs.add_argument(
        "--thumb-width",
        type=int,
        default=make_thumbs.THUMB_SIZE[0],
        help=f"Thumbnail width in pixels (default: {make_thumbs.THUMB_SIZE[0]})",
    )
    p_thumbs.add_argument(
        "--thumb-height",
        type=int,
        default=make_thumbs.THUMB_SIZE[1],
        help=f"Thumbnail height in pixels (default: {make_thumbs.THUMB_SIZE[1]})",
    )
    p_thumbs.set_defaults(func=cmd_make_thumbs)

    # -- make-pptx --
    p_pptx = sub.add_parser(
        "make-pptx",
        help="Build a .pptx from script.md slide order.",
    )
    p_pptx.add_argument(
        "--deck",
        required=True,
        choices=list(ALL_DECKS),
        metavar="DECK",
        help=f"slide deck to export (one of: {', '.join(ALL_DECKS)})",
    )
    p_pptx.add_argument(
        "--script",
        type=pathlib.Path,
        default=None,
        help="Path to script.md (default: deck's script.md)",
    )
    p_pptx.add_argument(
        "--output",
        type=pathlib.Path,
        default=None,
        help="Path to output .pptx (default: <deck-dir>/<deck>.pptx)",
    )
    p_pptx.set_defaults(func=cmd_make_pptx)

    # -- render-slides --
    p_slides = sub.add_parser(
        "render-slides",
        help="Render slide PNGs from Python source.",
    )
    p_slides.add_argument(
        "--deck",
        required=True,
        choices=list(ALL_DECKS),
        metavar="DECK",
        help=f"slide deck to render (one of: {', '.join(ALL_DECKS)})",
    )
    p_slides.add_argument(
        "slide",
        nargs="?",
        metavar="SLIDE",
        help="slide to render (omit to render all slides in the deck)",
    )
    p_slides.add_argument(
        "--html-only",
        action="store_true",
        default=False,
        help="generate only the interactive HTML, skip PNG screenshots (multi-step slides only)",
    )
    p_slides.set_defaults(func=cmd_render_slides)

    args = parser.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()
